ALTER TABLE "tickets" DROP CONSTRAINT "tickets_blocked_reason_check";--> statement-breakpoint
ALTER TABLE "tickets" ADD CONSTRAINT "tickets_blocked_reason_check" CHECK (("tickets"."state" = 'blocked') = ("tickets"."blocked_reason" is not null) and ("tickets"."blocked_reason" is null or "tickets"."blocked_reason" in ('gate-failed', 'post-merge-gate-failed', 'merge-conflict', 'protected-path-changed', 'no-commits', 'agent-gave-up', 'contract-change-needed', 'invalid-output', 'timeout', 'integration-loop-exceeded', 'upstream-cancelled', 'job-failed')));